package vn.edu.eaut.lab5.ui;
import vn.edu.eaut.lab5.bus.*;import vn.edu.eaut.lab5.model.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.math.BigDecimal;import java.util.List;
public class SanPhamPanel extends JPanel {private final SanPhamBUS bus=new SanPhamBUS();private final DanhMucBUS dmBus=new DanhMucBUS();private final JTextField id=new JTextField(),name=new JTextField(),price=new JTextField(),stock=new JTextField(),query=new JTextField(),priceFrom=new JTextField(),priceTo=new JTextField(),stockFrom=new JTextField(),stockTo=new JTextField();private final JComboBox<DanhMuc> category=new JComboBox<>();private final JComboBox<String> sort=new JComboBox<>(new String[]{"Ma","Ten","Don gia"});private final JButton add=new JButton("Them"),edit=new JButton("Sua"),del=new JButton("Xoa"),refresh=new JButton("Lam moi"),find=new JButton("Tim kiem"),first=new JButton("Dau"),prev=new JButton("Truoc"),next=new JButton("Sau"),last=new JButton("Cuoi");private final JLabel pageLabel=new JLabel("Trang 1 / 1");private final DefaultTableModel model=new DefaultTableModel(new Object[]{"Ma SP","Ten san pham","Don gia","So luong","Danh muc"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private int page,totalPages=1;private static final int PAGE_SIZE=10;
 public SanPhamPanel(){setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(10,10,10,10));id.setEditable(false);JPanel f=new JPanel(new GridLayout(5,2,8,8));f.add(new JLabel("Ma san pham:"));f.add(id);f.add(new JLabel("Ten san pham:"));f.add(name);f.add(new JLabel("Don gia:"));f.add(price);f.add(new JLabel("So luong ton:"));f.add(stock);f.add(new JLabel("Danh muc:"));f.add(category);JPanel a=new JPanel(new FlowLayout(FlowLayout.LEFT));for(JButton b:new JButton[]{add,edit,del,refresh})a.add(b);JPanel q=new JPanel(new GridLayout(2,6,5,5));q.add(new JLabel("Ten:"));q.add(query);q.add(new JLabel("Gia tu:"));q.add(priceFrom);q.add(new JLabel("Gia den:"));q.add(priceTo);q.add(new JLabel("Ton tu:"));q.add(stockFrom);q.add(new JLabel("Ton den:"));q.add(stockTo);q.add(sort);q.add(find);JPanel top=new JPanel(new BorderLayout(5,5));top.add(f,BorderLayout.NORTH);top.add(a,BorderLayout.CENTER);top.add(q,BorderLayout.SOUTH);add(top,BorderLayout.NORTH);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);table.setRowHeight(25);add(new JScrollPane(table),BorderLayout.CENTER);JPanel nav=new JPanel(new FlowLayout(FlowLayout.CENTER));for(JButton b:new JButton[]{first,prev,next,last})nav.add(b);nav.add(pageLabel);add(nav,BorderLayout.SOUTH);add.addActionListener(e->save(true));edit.addActionListener(e->save(false));del.addActionListener(e->delete());refresh.addActionListener(e->{clear();page=0;load();});find.addActionListener(e->{page=0;load();});query.addActionListener(e->{page=0;load();});for(JButton b:new JButton[]{first,prev,next,last})b.addActionListener(e->navigate((JButton)e.getSource()));category.addActionListener(e->{if(isShowing()){page=0;load();}});sort.addActionListener(e->{if(isShowing()){page=0;load();}});table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting())fill();});loadCategories();load();}
 private void navigate(JButton b){if(b==first)page=0;else if(b==prev&&page>0)page--;else if(b==next&&page<totalPages-1)page++;else if(b==last)page=totalPages-1;load();}
 private void loadCategories(){new SwingWorker<List<DanhMuc>,Void>(){protected List<DanhMuc> doInBackground()throws Exception{return dmBus.findAll();}protected void done(){try{category.removeAllItems();for(DanhMuc x:get())category.addItem(x);}catch(Exception e){error("Khong the tai danh muc",e);}}}.execute();}private Integer categoryId(){DanhMuc d=(DanhMuc)category.getSelectedItem();return d==null?null:d.getMaDm();}private BigDecimal decimal(String s){return s.isBlank()?null:new BigDecimal(s.trim());}private Integer integer(String s){return s.isBlank()?null:Integer.valueOf(s.trim());}
 private void load(){setButtonsEnabled(false);new SwingWorker<Object[],Void>(){protected Object[] doInBackground()throws Exception{String n=query.getText();BigDecimal pf=decimal(priceFrom.getText()),pt=decimal(priceTo.getText());Integer sf=integer(stockFrom.getText()),st=integer(stockTo.getText()),dm=categoryId();int count=bus.count(n,pf,pt,sf,st,dm);List<SanPham> rows=bus.search(n,pf,pt,sf,st,dm,sort.getSelectedIndex()==1?"ten":sort.getSelectedIndex()==2?"gia":"ma",PAGE_SIZE,page*PAGE_SIZE);return new Object[]{count,rows};}protected void done(){try{Object[] result=get();int count=(Integer)result[0];totalPages=Math.max(1,(count+PAGE_SIZE-1)/PAGE_SIZE);if(page>=totalPages)page=totalPages-1;model.setRowCount(0);for(SanPham x:(List<SanPham>)result[1])model.addRow(new Object[]{x.getMaSp(),x.getTenSp(),x.getDonGia(),x.getSoLuong(),x.getTenDm()==null?"":x.getTenDm()});pageLabel.setText("Trang "+(page+1)+" / "+totalPages);first.setEnabled(page>0);prev.setEnabled(page>0);next.setEnabled(page<totalPages-1);last.setEnabled(page<totalPages-1);}catch(Exception e){error("Khong the tai san pham",e);}finally{setButtonsEnabled(true);}}}.execute();}
 private void save(boolean isNew){try{SanPham x=read();if(!isNew){if(id.getText().isBlank())throw new IllegalArgumentException("Chon san pham can sua");x.setMaSp(Integer.parseInt(id.getText()));}if(bus.save(x)){clear();load();}}catch(Exception e){error("Khong the luu san pham",e);}}private SanPham read(){int q;try{q=Integer.parseInt(stock.getText().trim());}catch(NumberFormatException e){throw new IllegalArgumentException("So luong phai la so nguyen");}BigDecimal p;try{p=new BigDecimal(price.getText().trim());}catch(NumberFormatException e){throw new IllegalArgumentException("Don gia khong hop le");}DanhMuc d=(DanhMuc)category.getSelectedItem();return new SanPham(0,name.getText().trim(),p,q,d==null?0:d.getMaDm(),d==null?null:d.getTenDm());}
 private void delete(){try{if(id.getText().isBlank())throw new IllegalArgumentException("Chon san pham can xoa");if(JOptionPane.showConfirmDialog(this,"Xoa san pham nay?","Xac nhan",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION&&bus.delete(Integer.parseInt(id.getText()))){clear();load();}}catch(Exception e){error("Khong the xoa san pham",e);}}private void fill(){int r=table.getSelectedRow();if(r<0)return;id.setText(model.getValueAt(r,0).toString());name.setText(model.getValueAt(r,1).toString());price.setText(model.getValueAt(r,2).toString());stock.setText(model.getValueAt(r,3).toString());String s=String.valueOf(model.getValueAt(r,4));for(int i=0;i<category.getItemCount();i++)if(category.getItemAt(i).getTenDm().equals(s))category.setSelectedIndex(i);}private void clear(){id.setText("");name.setText("");price.setText("");stock.setText("");table.clearSelection();}private void setButtonsEnabled(boolean b){for(JButton x:new JButton[]{add,edit,del,refresh,find})x.setEnabled(b);}private void error(String t,Exception e){Throwable x=e.getCause()==null?e:e.getCause();JOptionPane.showMessageDialog(this,t+": "+x.getMessage(),"Loi",JOptionPane.ERROR_MESSAGE);}}
